// ---- modifier constructors -------------------------------------------------
const M = {
  fixed:  (stat, delta) => ({t:'fixed', stat, delta}),
  choice: (options) => ({t:'choice', options}),                 // options: [{stat,delta}, ...] pick 1, auto-random unless flagged
  choiceMixed: (options) => ({t:'choiceMixed', options}),        // options: [ [mods...], [mods...] ] pick one bundle
  distribute: (points, among, maxPer=1) => ({t:'distribute', points, among, maxPer}),
  reduceDistinct: (count, among, delta=-1) => ({t:'reduceDistinct', count, among, delta}),
  roleplay: (label, among) => ({t:'roleplay', label, among}),    // needs manual player choice, never auto-random
  weaponChoice: (amongCombatSkills, label='Любимое оружие') => ({t:'weaponChoice', label, among: amongCombatSkills}), // free (non-roleplay) choice of a weapon category -> resolves into an ability, not a stat
  abilityChoice: (name, among, textFn) => ({t:'abilityChoice', name, among, textFn}), // free choice of a stat that the resulting text refers to -> resolves into an ability, not a stat bonus
  ability: (name, text) => ({t:'ability', name, text}),
  // Grants one specific, already-named psi ability outright (no player pick involved) — for the rare
  // case where a career/origin fixes a particular catalog ability by name (e.g. "Ментальные ресурсы"
  // career always gives "Считка личности"), as opposed to mysticPick's player-facing discipline/tier
  // choices. Looks the name up in PSI_ABILITY_CATALOG at apply time to get its discipline/tier and the
  // real book text from ABILITY_TEXT_LOOKUP, and registers the discipline as known — plain M.ability()
  // can't do any of that, it only stores whatever flavor text is passed to it verbatim.
  psiGrant: (name) => ({t:'psiGrant', name}),
  // Архетипные способности вида "Позволяет применять X, даже если пси-способность ещё не изучена.
  // Если X была или будет изучена повторно другим способом, она усиливается: ...". Раньше такие
  // способности (Телекинетик/Мясник и ещё 8 подобных по всему листу) писались обычным M.ability() —
  // текст верно ОПИСЫВАЛ эффект, но механически ничего не выдавал персонажу и не усиливал каталожную
  // способность, если та уже была или появлялась позже. name/text — как у M.ability (сама архетипная
  // способность остаётся отдельной строкой, как и раньше). psiName — имя РЕАЛЬНОЙ каталожной
  // пси-способности из PSI_ABILITY_CATALOG, которую нужно выдать (если её ещё нет) или усилить (если
  // она уже есть/появится потом). Важно: в тексте многих таких способностей упоминается название
  // конкретной ТЕХНИКИ (например "архивация плоти"), а не самой каталожной способности — она может
  // быть описана ВНУТРИ текста другой, шире называющейся каталожной способности (например "архивация
  // плоти" — часть текста способности "Психоконструкция", см. ABILITY_TEXT_LOOKUP) — тогда psiName
  // должен быть именем именно этой каталожной способности-контейнера, не отдельной техники внутри неё.
  // enhanceText — сам текст усиления, показывается жирным курсивом рядом с каталожной способностью в
  // renderAbilities, если она усилена (см. case 'psiGrantOrEnhance' и поля enhancedText/enhancedSource).
  psiGrantOrEnhance: (name, text, psiName, enhanceText) => ({t:'psiGrantOrEnhance', name, text, psiName, enhanceText}),
  abilityPool: (source, group, options, count=1, meta={}) => ({t:'abilityPool', source, group, options, count, meta}),
  mysticPick: (kind, data={}) => ({t:'mysticPick', kind, data}),
  appearance: (delta) => ({t:'appearance', delta}), // definite (non-optional) shift to the внешний вид tracker
  size: (delta, max) => ({t:'size', delta, max}), // definite (non-optional) shift to the размер tracker; max — потолок источника («не более 3»)
  sizeOption: (delta) => ({t:'sizeOption', delta}), // «может взять размер −1 / поднять на +1» — вопрос игроку (shiftSize: сила и скрытность сдвигаются вместе с размером)
  psiSoprot: (delta) => ({t:'psiSoprot', delta}), // definite shift to пси-сопротивление (e.g. подтип "Мастер плоти")
  hpBySize: (plus) => ({t:'hpBySize', plus}), // «Здоровяк»: максимум ОЗ +[размер + plus] — пересчитывается вместе с размером (hpMax)
  sturdyWeapon: () => ({t:'sturdyWeapon'}), // «Крепкий середнячок»: «Любимое оружие», а если уже есть — навык боя +2 (не выше 4)
  bonusHpMax: (delta) => ({t:'bonusHpMax', delta}), // e.g. "Живучий: максимум ОЗ повышается на 1"
  bonusPsiMax: (delta) => ({t:'bonusPsiMax', delta}), // e.g. Боевой психоник's "Душевная стойкость" (+2 max пси)
  item: (text) => ({t:'item', text}),
  religion: (options) => ({t:'religion', options}),
  note: (text) => ({t:'note', text}),
  table: (label, diceMax, rows) => ({t:'table', label, diceMax, rows}), // rows: [{min,max,text}]
  itemTable: (label, diceMax, rows, rolls=1) => ({t:'itemTable', label, diceMax, rows, rolls}), // grants `rolls` items from the table — auto-rolled in random mode, offered as a pick in manual mode
  itemBundle: (label, diceMax, rows, rolls=1) => ({t:'itemBundle', label, diceMax, rows, rolls}), // rows with `fixed:[{name,weight}]` (always granted) + optional `choice:[{name,weight}]` (pick one) + optional `credits`
  itemSet: (items) => ({t:'itemSet', items}), // fixed list of {name,weight} (all granted) mixed with {choice:[{name,weight},...]} (pick one) entries — for a career's flat item grant, not a random table
  credits: (amount, label) => ({t:'credits', amount, label}) // amount: number or ()=>number (for dice-based sums); always resolves immediately, never a choice
};

