const THEOLOGY_NOTE = 'Теология: считается равной Значению жизни высшего света (по умолчанию), либо учения дикарей (если религия — вера в духов Асу), либо пересуд люда (если поклонение Матери Природе). Выберите характеристику согласно религии персонажа.';
