    14:[M.fixed('volya',1), M.choice(PERSONALITY.filter(s=>s!=='volya').map(s=>({stat:s,delta:1}))),
        M.fixed('mistika',1), M.roleplay('Знания и навыки: +1 к знанию старого/нового мира (кроме мистики) или навыку в зависимости от отыгрыша', CULTIST_KNOW_SKILL_POOL)],
    15:[M.fixed('mistika',1), M.roleplay('Знания и навыки: +1 к знанию старого/нового мира (кроме мистики) или навыку в зависимости от отыгрыша', CULTIST_KNOW_SKILL_POOL),
        M.fixed('mistika',1), M.roleplay('Знания и навыки: +1 к знанию старого/нового мира (кроме мистики) или навыку в зависимости от отыгрыша', CULTIST_KNOW_SKILL_POOL),
        M.ability('Психонетический транс','Доплатив 1 пси и 1 удачу, псионик наделяет пси-способность чудовищной мощью. Псионик направляет такую способность по стандартным для неё правилам, однако способность срабатывает не только в точке применения, а и в окружающей её области в форме куба со стороной 9 м. Проверка срабатывания способности проходится лишь против попавших в область действия важных для истории персонажей, а провал её с любой категорией не несёт для псионика никаких Невзгод. На всех остальных попавших в область действия способности второстепенных персонажей и статистов способность срабатывает с автоматической 2-й категорией успеха. Все спорные моменты по применению психонетического транса остаются на усмотрение мастера.')],
