const ABILITY_TEXT_LOOKUP = {
  "Чудо веры": "Раз в день персонаж может перебросить проверку способности культового символа своей веры.",
  "Считка личности": "Псионик получает возможность считывать эманации пси-поля и понимать эмоции осознанных созданий, разумных ИИ, теней, пустот и т.д. Псионик действием тратит 1 пси и совершает Бросок мистики (−3), концентрируясь на обозримой цели в пределах 12 м. За каждую категорию успеха он выбирает одно из: ближайший час читать все эмоции цели и понимать её отношение к каждому объекту в пределах 12 м; получить ментаобраз цели, понять её состояние здоровья, наличие пси-мутаций; осознать все сильные эмоции цели и связанные с ними события за предыдущие [мистика] дней; понять сильные и слабые стороны характера цели, её жизненную мотивацию. Успех и на к20 значение выше 15: осознать все пиковые эмоции цели и связанные с ними события за [мистика] лет, рассмотреть настоящий ментаобраз цели, даже если тот скрыт. Полностью понять темперамент цели, получая возможность предсказывать её поступки в дальнейшем при успешных Бросках смекалки (−3).",
  "Псиметрия": "Псионик получает возможность считывать эманации пси-поля и оценивать их характер, а также ответственных за них личностей. Псионик действием тратит 1 пси и совершает Бросок мистики (−3), концентрируясь на обозримом предмете или месте в пределах 12 м. За каждую категорию успеха он выбирает что-то одно из: получить чёткий ментаобраз основного психологического пользователя объекта и понять характер их связи; получить ментаобраз объекта и узреть одно самое эмоциональное событие, произошедшее недалеко от объекта (или с объектом); получить слабые ментаобразы личностей, оставивших на объекте следы, последних проходивших мимо или касавшихся его, менее значимых владельцев; узреть внешность основного психологического пользователя объекта на уровне органов чувств — внешний вид, запах и т.д. Успех и на к20 значение выше 15: сосредоточившись на объекте, псионик может визуально воссоздать любую картину, когда-либо происходившую рядом. Псионик получает сразу так много информации, что ошеломлён на 3 секунды. Примечание. Если мистика сенсорика 12+, он может при помощи этой способности понять значение кармы существа, и подвержено ли это существо влиянию реинкарнатора.",
  "Ясновидение": "Сенсорные чувства псионика проникают глубоко в пространство-время и дают ему возможность чувствовать грядущее, помогая и оберегая от бед. Псионик действием тратит 1 пси и совершает Бросок мистики (−3), получая [категория успеха] предзнаменований. Каждое предзнаменование должно быть сразу каким угодно образом распределено между выбранными псиоником разумными целями, включая его самого. Чтобы передать предзнаменование, псионик тратит 5 минут, пересказывая его цели. Теперь до конца дня каждое предзнаменование может быть потрачено целью на то, чтобы перед проверкой к20 добавить +3 к её Максимуму, но не более 1 предзнаменования на одну проверку.",
  "Сенсорная иллюзия": "Псионик получает возможность влиять на сенсорные чувства других людей. Действием псионик тратит 2 пси и совершает Бросок мистики против смекалки или восприятия видимой цели на её выбор. В случае успеха псионик меняет исходящую от органов чувств цели информацию на [10 за категорию успеха] минут. Если псионик не очень хорошо знаком с иллюзорным объектом, то проверка Осложнена. Если цель получает раны или иллюзия извне очевидно подвергается сомнению, то цель совершает Бросок смекалки, при успехе сбрасывая эффект способности.",
  "Поиск ментаследа": "Псионик может отслеживать эманации пси-поля, их прошлые отголоски и двигаться по их следу. Действием концентрируясь на обозримой области площадью до 1 м2, псионик объявляет, след какой цели или объекта он в ней ищет. Псионик тратит 2 пси и совершает Бросок мистики (−3). Проверка Осложнена, если псионик не очень хорошо знаком с искомым объектом. В случае успеха псионик понимает, есть ли в указанной области след искомого объекта. Если след есть, то псионик узнаёт, были ли перемещения искомого объекта эмоционально связаны с любым знакомым ему ментаобразом. Псионик может двигаться по следу искомого объекта ещё [выпавшее на к20 значение] часов.",
  "Провидение": "Сенсорик учится осознавать пространство, распространяя свой внутренний взор далеко за пределы обозримого. Желая увидеть удалённое место или объект, провидец тратит 10 минут спокойной концентрации, 2 пси и совершает Бросок мистики (−6). Если псионик не очень хорошо знаком с иллюзорным объектом, то проверка Осложнена. Получая успех, провидец перемещает свой атман к цели, не получая никакой уточняющей информации о её расположении. Провидец может поддерживать способность [10 за категорию успеха] минут. Пока атман провидца находится в указанном месте, тот видит и слышит всё происходящее — звук доносится словно сквозь воду, а изображение размыто и имеет временные шлейфы. Кроме того, провидец считывает основные эмоциональные состояния окружающих, их ментаобразы и может применять пси-способности. В момент появления атмана провидца в новом месте, чтобы не быть обнаруженным, провидец должен совершить Упрощённый Бросок мистики против мистики каждого способного увидеть его псионика; получает Осложнение за каждое из таких качеств у противника, как применение способностей сенсорики или знание его ментаобраза. Если провидец решает тайно применить какие-то пси-способности, он вновь должен успешно пройти проверку, чтобы не быть обнаруженным. Атман существует в одном измерении с духами и без проверки заметен любому Асу поблизости, видим для пустот и материален для пустот, их частей тел, реликвий и других объектов пси-плоскости. На атман владельца можно воздействовать мистическими способностями, его могут атаковать тени, Асу и пустоты, а также оружие, способное поражать объекты пси-плоскости, при этом все полученные раны проявляются на теле провидца. Примечание! Если мистика сенсорика выше 9, он может применять провидение действием вместо 10 минут спокойной концентрации.",
  "Прекогниция": "Сенсорик учится осознавать время, транспортируя свой внутренний взор вверх по его течению. Чтобы совершить предсказание, псионик должен погрузиться в часовой транс, затратить 3 пси и преуспеть в Броске мистики (−6). Псионик может применить предсказание свободным действием, но тогда цена способности возрастёт на 1 пси. В случае успеха псионик раздвигает пространство-время и получает 1 удачу за каждую категорию успеха. Такие очки удачи символизируют сведения о ближайшем будущем и хранятся одну неделю. Псионик может их использовать сам или отдать любому другому персонажу без траты хода в любой момент, если другой персонаж может слышать его.",
  "Телекинетика": "Псинетик получает возможность манипулировать и перемещать твёрдые объекты материального мира. Важно! Чтобы манипулировать не твёрдыми объектами, а чем-то сложнее (жидкостями, газами, энергетическими частицами и т.д.), псионик должен дополнительно освоить способность псинетика. Телекинез: затратив 1 пси, персонаж реакцией выбирает твёрдый объект размера до −2 (вещь весом ~20 кг) в пределах [мистика] м вокруг себя и перемещает в новую точку в этих же пределах. Чтобы переместить нечто более крупное, псионик должен затратить действие и преуспеть в Броске мистики. В любом случае объект не должен быть размера 1+. Если цель движется, то проверка Осложнена. Если псионик хочет метнуть несогласное и способное двигаться существо или объект (например, игуану), он должен затратить действие и преуспеть в Осложнённом Броске мистики против рефлексов цели (или другой характеристики, если это уместно на взгляд мастера). Если псионик метает объект в существо с намерением нанести урон, то оно должно преуспеть в Броске рефлексов против мистики псионика, или получит попадание с МУ 10 удар, раны 2. Опциональное правило. Когда псионик пытается вырвать предмет из рук у цели, та может удержать предмет, если до проверки телекинеза преуспеет в Броске силы против мистики псионика. Если цель удержала предмет, то проверка телекинеза проходит так, будто псионик пытается переместить однородный объект размером с [цель плюс зажатый ею предмет, если размер предмета важен].",
  "Термокинез": "Псинетик получает возможность манипулировать энергией окружающего мира, придавать или отнимать её у объектов, менять при помощи неё агрегатные состояния, направлять её потоки по своему усмотрению. Пирокинез: затратив действие и 1 пси, псионик совершает Бросок мистики, при успехе ускоряя электроны и создавая несущийся направленный сгусток плазмы, поражающий все видимые и стоящие на одной линии цели в пределах 12 метров и наносящий им [категория успеха] попаданий с МУ 12 температура, раны 2. Пси-сопротивление не может помочь против этой способности, поскольку псионик влияет на среду, а не на сами цели. Категория успеха 1 и 2: псионик создаёт низкотемпературный вариант плазмы — рокочущий поток пламени. Значимые для истории персонажи в области поражения могут реакцией совершить Бросок рефлексов (−3), при успехе избегая опасности. Категория успеха 3: с раскатом грома псионик создаёт дуговой электрический разряд с типом попадания «энергия». От такого разряда нельзя увернуться. Бытовой пирокинез: кроме испепеления врагов, псинетик может без затраты пси коснуться предмета размером с 1 Вещь и быстро его нагреть до 45 градусов или охладить до 4; на 10 секунд зажечь в руке пламя, как от зажигалки; создать из воды льдинку размером с палец; пустить электрический разряд касанием — слабый, но болезненный, как укус пчелы. Чтобы применить бытовой пирокинез, псинетик должен затратить действие и пройти Бросок мистики. Псинетик в любом случае добивается необходимого эффекта, однако при провале с итогом 15− он тратит 1 пси.",
  "Псинетика": "Силой своего дара псионик получает возможность манипулировать окружающим пси-пространством, вызывая отголоски в реальном мире. Это может быть движение газов и жидкостей, гравитационные всплески, электромагнитные колебания и т.д. Дальний телекинетический удар: затратив действие и 1 пси, псионик совершает Бросок мистики против рефлексов видимой цели в пределах 90 м. В случае успеха псионик создаёт направленную гравитационную волну, наносящую цели попадание (МУ 12 удар, раны 2, пул) и отбрасывающую на 3 м в выбранную псиоником сторону. Значимая для истории цель не будет отброшена, если преуспеет в Броске силы против мистики псионика.",
  "Психоскопия": "Псионик получает возможность чувствовать вибрации окружающей материи и её текущее состояние. Важно! Эта способность может быть изучена, только если псионик обладает способностью термокинез. Ментальный взор: затратив 1 пси, псинетик активирует свой ментальный взор на [мистика] минут, выступая датчиком движения или сонаром на расстоянии 60 м вокруг себя. Если псионик владеет ещё и способностью псинетика, то он выступает анализатором газов, жидкостей и окружающих полей. Пси-щит: затратив реакцию и 1 пси, персонаж совершает Бросок мистики (−3), в случае успеха отклоняя или поглощая [категория успеха] попаданий, исходящих от видимой угрозы и направленных против псионика или одной видимой цели в пределах [мистика] м. Персонаж может прикрыться пси-щитом от попаданий типа: энергия, температура, взрыв. Чтобы защититься от патронов, рукопашных ударов и метательных снарядов, персонаж должен владеть пси-способностью псинетика. Примечание! Если мистика псионика выше 9, он больше не обязан тратить на пси-щит реакцию, а может применять его свободным действием. Если мистика псионика 12 и выше, то он может применять пси-щит против одной атаки множество раз.",
  "Психоконструкция": "Псионик получает возможность создавать (лепить) объекты под действием своей воли. Важно! Эту способность можно выучить, лишь обладая тривиальной способностью телекинетика, а отсутствие владения двумя другими тривиальными способностями психокинетики будет давать по модификатору −3 за каждую на попытку применить любые возможности психоконструкции. Архивация плоти: действием затрачивая 2 пси, псионик совершает Бросок мистики против рефлексов цели, находящейся в пределах 30 м. В случае успеха псионик начинает неестественно изгибать конечности цели под жуткий хруст её ломающихся костей, стремясь свернуть в мясной ком. Подвергшаяся сжатию цель теряет реакцию и получает 4 попадания с МУ 12 удар, раны [1 + категория успеха]. Если размер цели 3 и меньше, то во время успешной архивации плоти её поднимает над землёй. Ментальное конструирование: представив в своей голове монолитный объект, не превышающий Огромной Вещи (~20 кг), псионик может свободным действием потратить 2 пси и совершить Бросок мистики (−3). В случае успеха он телекинезом собирает из доступных и незащищённых предметов вокруг куски и мгновенно формирует целевой объект в пределах 12 м. Для сложных конструкций псионик должен обладать профильными знаниями (например, чтобы создать стетоскоп — разбираться в медицине). Если он хочет создать объект из нескольких деталей, то тратит действие и может добавлять к конструкции +1 деталь за каждую категорию успеха. Псионик не может использовать способность для разрушения или деактивации предметов, находящихся под физическим контролем других существ.",
  "Хронокинетика": "Псионик получает возможность осознавать мир вне течения времени и даже контролировать его. Временные аномалии и вынужденные путешествия сквозь пространство-время теперь как открытая книга для персонажа. Данное осознание даёт сильное давление на самоидентификацию личности обычного человека и делает сумасшедшим псионика, дух которого 6 и ниже, наделяя его случайным безумием. Важно! Эту способность можно выучить, лишь обладая тривиальной способностью псинетика, а отсутствие владения двумя другими тривиальными способностями психокинетики будет давать по модификатору −3 на проверку хронокинетики. Стазис: затратив действие и 3 пси, псионик совершает Бросок мистики (−3). В случае успеха он замедляет течение времени для объектов и существ, находящихся внутри куба 6×6×6 м в пределах 12 м на [1 + категория успеха] кругов. Только те объекты, которые находились в области в момент активации, попадают под эффект. В это время все существа и объекты внутри считаются выведенными из хода времени: они не могут двигаться, действовать и на них нельзя влиять способами, требующими реакции цели или точного взаимодействия с её состоянием (атака, лечение и т.д.). Существа игнорируют стазис, если результат к20 псионика равен или ниже их пси-сопротивления, и не получают от пси-сопротивления других преимуществ.",
  "Квантовая псинетика": "Псионик получает возможность повелевать окружающим пространством. Пространственное перемещение: затратив действие и 2 пси, псионик совершает Бросок мистики (−3), чтобы мгновенно переместить своё тело со всей амуницией в любую видимую им область. Псионик с пси-способностями 12 и выше может применять данную способность не действием, а реакцией. Перемещение: затратив действие, 1 удачу и 3 пси, псионик совершает Бросок мистики, чтобы на мгновение вытянуть всех касающихся его согласных персонажей из реального мира и перенести в любой виденный им ранее реинкарнатор. Каждый перемещаемый таким образом персонаж переживает психический коллапс и должен потерять 1 пси и совершить Бросок воли (−3), теряя ещё 1 пси при провале.",
  "Контроль инфополя": "Псионик осваивает способность управлять окружающим информационным полем и направлять его потоки. Мыслешок: псионик действием тратит 1 пси и совершает Бросок мистики против воли видимой цели. В случае успеха он перенаправляет информационные потоки окружающего пси-поля в разум цели и коллапсирует её сознание. Категория успеха 1: все действия цели Осложнены. Категория успеха 2: разум цели отключается, она теряет связь с миром, садится на землю и не двигается. Категория успеха 3: биологическая цель падает на пол, её сознание и нервная система коллапсируют, сфинктеры разжимаются, организм забывает, как поддерживать свои базовые функции — дыхание, сердцебиение и т.д. В конце каждого круга цель проходит спасбросок от смерти с Максимумом 17 (если ОЗ цели 0 и ниже, то Максимум снижается до 12). В начале каждого круга цель совершает спасбросок воли (−6), при успехе прекращая эффект мыслешока.",
  "Ментащит": "Псионик приобретает способность закрывать разум от чужого вмешательства, других псиоников или Асу. Ментащит: затратив 1 пси и 30 минут концентрируясь над собой или видимой и находящейся рядом целью, псионик совершает Бросок мистики, в случае успеха на сутки создавая вокруг цели ментащит с прочностью [категория успеха] условных единиц. Ментащит направлен на то, чтобы предотвратить влияние на разум цели извне, однако никак не может препятствовать переживаниям самой цели (например, страху, радости и т.д.). Ментащит полностью скрывает ментаобраз цели, её эмоции от сенсориков и взора духов Асу, от ориентированных на переживания теней и пустот (скрывает эмоции, но не делает цель невидимой). Если цель укрыта ментащитом и в проверке против мистической способности участвует её воля, то воля цели в такой проверке будет на 6 больше. Каждый раз, как ментащит оказывает влияние на проверку, он теряет 1 заряд из своей прочности, пока полностью не разрушится.",
  "Телепатическая связь": "Псионик получает возможность связывать разумы разных существ и являться буфером по обмену информации между ними. Телепатическая связь: затратив 1 пси и действие, псионик совершает Бросок мистики. В случае успеха на 3 часа он создаёт телепатическую связь между собой и ещё [категория успеха] согласными и видимыми на момент создания связи существами. Все объединённые данной связью существа могут мысленно общаться между собой. Псионик служит маршрутизатором всех переговоров между такими целями и в любом случае слышит каждого из них. Особенности телепатической связи: если цель укрыта за материалом с пси-сопротивлением выше 3, то связь с ней невозможна. Если мистика псионика ниже 6, то он тратит часть сил на поддержку такой связи, совершая параллельные проверки мистики с модификатором −3. Если псионик пытается включить в связь цель, не желающую этого, то должен преуспеть в Броске мистики против воли цели.",
  "Внушение": "Псионик получает возможность внушать другому человеку ложные воспоминания, манипулировать мыслями. Внушение: затратив 3 пси и 5 минут концентрации над видимой, находящейся в пределах 12 м целью, псионик совершает Бросок мистики против воли цели. В случае успеха псионик вкладывает в голову цели короткий информационный факт, не касающийся ключевых моментов, регулярных действий или важных воспоминаний из её жизни. Если при проверке внушения на к20 выпало значение больше духа цели, то псионик получает больше власти и может полностью изменить или добавить важную сцену в воспоминаниях цели. Чтобы понять, что разум цели подвергся внушению, другой псионик должен преуспеть в способности взлом разума минимум с той же категорией успеха, что и совершивший внушение телепат. Примечание. Если мистика псионика выше 9, то он может применять внушение действием, вместо траты 5 минут на концентрацию.",
  "Биологический контроль": "Псионик осваивает способность через архаичные и базовые части мозга управлять биологическими процессами в организмах живых существ. Разрушение тела: затратив действие и 2 пси, псионик совершает Бросок мистики против выносливости видимой, находящейся в пределах 60 м цели, в случае успеха нарушая жизнедеятельность её организма. Категория успеха 1: цель теряет 1 ОЗ и действие, поскольку её непроизвольно тошнит кровью. Категория успеха 2: цель теряет 3 ОЗ и действие, её внутренности сводит судорогой, цель непроизвольно блюёт и испражняется кровью. Категория успеха 3: цель теряет 4 ОЗ и действие, её сердце бешено колотится, на поверхности кожи выделяется кровавый пот, цель непроизвольно блюёт и испражняется кровью — она должна пройти спасбросок от смерти с Максимумом 17, умирая от кровоизлияния в мозг или разрыва сердца в случае провала. Стабилизация: затратив действие и 1 пси, псионик может попытаться стабилизировать существо, находящееся в пределах 12 м от него. Для этого он должен преуспеть в Броске мистики −12. Псионик управляет имеющимися у организма ресурсами, поэтому может совершать лишь стабилизацию и не может этой способностью оказывать другие виды медицинской помощи. Регенерация: затратив 1 пси, псионик может на 24 часа повысить регенеративные функции [мистика] целям, если те после проводят с псиоником более 12 следующих часов. Каждый раз, когда такая цель должна восстановить ОЗ, она восстанавливает на 1 ОЗ больше, а её отдых +3.",
  "Взлом разума": "Псионик осваивает возможность вламываться в разум живых существ и считывать хранящиеся там данные. Взлом разума: затратив 3 пси и 5 минут концентрации над видимой, находящейся в пределах 12 м целью, псионик совершает Бросок мистики против воли цели. В случае успеха псионик считывает текущие мысли цели и самую поверхностную информацию: имя, возраст, постоянное место жительства, лица близких и т.д. Категория успеха 2: псионик получает ещё ворох мыслей цели за последний день и может узнать часто используемые целью знания, постоянные маршруты и регулярные линии поведения. Категория успеха 3: псионик может воссоздать все сохранившиеся за неделю воспоминания цели, как свои собственные, получает доступ к ключевым для цели событиям в её жизни, скрытым мотивам, редко используемым данным и т.д. Успех и на к20 значение выше 15: псионик полностью открывает разум цели, получая доступ к совсем давним воспоминаниям и даже к обрывкам забытых деталей. Примечание! Если мистика псионика выше 9, то он может применять взлом разума, затрачивая на концентрацию действие вместо 5 минут.",
  "Подчинение личности": "Телепат получает возможность подчинять разумы других существ, заставляя их повиноваться своей воле. Подчинение личности: затратив действие и 3 пси, псионик проходит Осложнённый Бросок мистики против воли видимой и находящейся в пределах 90 м цели. В случае успеха на ближайшие 10 минут псионик получает в своё повиновение личность цели со всеми её компетенциями. В случае успеха с Невзгодами цель может противиться приказам и совершать действия с помехой 3. В конце каждого своего хода за 1 пси цель может попробовать пройти Осложнённый Бросок воли против воли псионика, в случае успеха освобождаясь из-под его власти, а в случае провала с Невзгодами утрачивая силы к сопротивлению и оставаясь в его подчинении до конца дня. Попытки подчинить нечеловеческий разум Осложнены дополнительно.",
  "Вероятностный прогноз": "Псионик получает возможность заглядывать вперёд в пространственно-временную вариативность, проводя тщательный и продуманный анализ, пытаясь спрогнозировать наилучшее для себя будущее. Важно! Не владея этой способностью, псионик не может изучить ни одной другой способности в данной дисциплине. Вероятностный прогноз: аналитик реакцией тратит 2 пси и совершает Бросок смекалки (−3), за каждую категорию успеха получая 1 прогноз на ближайшие сутки. Теперь аналитик может: реакцией потратить прогноз и совершить Бросок мистики, при успехе запустить череду причинно-следственных событий, которые влияют на положение объекта в пространстве (игрок описывает, как он хочет повлиять на объект, а Мастер назначает модификатор проверки); реакцией потратить прогноз и совершить Бросок мистики против пси-сопротивления цели, в случае успеха предсказывая её ближайшие действия; действием потратить прогноз и совершить Бросок мистики против пси-сопротивления цели и в случае успеха преуспеть в проверке социального взаимодействия, влияя на поведение разумной цели (цель не будет действовать вопреки своим убеждениям, совершать что-то очевидно опасное или не имеющее под собой оснований); действием потратить прогноз и совершить Бросок мистики (−6), при успехе преуспеть в проверке, связанной с простыми и непродолжительными физическими действиями, даже если не владеет необходимыми для неё знаниями (например, осуществить экстренный ремонт). Важно! Аналитик не может выполнять при помощи вероятностного прогноза проверки, связанные с воспоминаниями или накопленными знаниями — это может быть только последовательно выполненный набор поступков, приводящих к физическому результату: проверка диалога с персонажем, починка, открытие двери и т.д. Кроме того, аналитик не может выполнять при помощи вероятностного прогноза действия, которые требуют концентрации на занятии более 5 минут.",
  "Мгновенный анализ": "Псионик получает возможность прогнозировать последствия своих ближайших действий. Мгновенный анализ: реакцией, затратив прогноз, псионик совершает Бросок мистики (−6), в случае успеха получая возможность в ближайшие [категория успеха] кругов совершать боевые проверки или краткосрочные физические действия (водить, контролировать падение и т.д.), опираясь на проверки смекалки, вместо назначенных мастером характеристик.",
  "Подготовка": "Псионик получает возможность планировать своё будущее загодя и может быть подготовленным к самым неожиданным поворотам судьбы. Я готов к этому: аналитик может прийти на выручку, внезапно выудив из запасов нужный предмет. Для этого он тратит прогноз и 4 часа на поиски на рынке, резервирует место на 1–3 Вещи в инвентаре и любую сумму денег, после чего совершает Бросок мистики (−6). За каждую категорию успеха в течение ближайших двух недель он может объявить, что тогда купил любой доступный в том же поселении предмет, не превышающий зарезервированное место и стоимость. Неиспользованные деньги и место возвращаются по истечении двух недель или если способность израсходована.",
  "Прогноз опасностей": "Псионик может заглядывать в ближайшую пространственно-временную вариативность, прогнозируя угрозы. Я предвидел это: псионик действием тратит 2 пси. Теперь в ближайшие [смекалка] часов, реакцией он может потратить прогноз и совершить Бросок мистики (−3), в случае успеха при помощи сценарной брони избегая одной не мистической угрозы. Мастер может попросить описать, как ему это удалось.",
  "Принцип домино": "Псионик получает возможность проектировать неочевидные вероятностные линии, создавая такие ситуации, когда брошенный посреди комнаты камень может привести к смерти вражеского лидера. Принцип домино: действием затратив прогноз, псионик совершает Бросок мистики (−6), анализируя поведение видимых им [категория успеха + 1] противников. В случае успеха он совершает неочевидную мелочь, которая по принципу домино создаёт помеху −3 на все физические действия для каждого целевого противника. Эта помеха длится 2 круга. Одновременно на одной цели может быть не более 1 такой помехи. Мастер может попросить описать, что именно сделал псионик. Я так и планировал: аналитик тратит прогноз и удачу. В формате флешбека коротко отыграйте одну ситуацию в прошлом, которая повлияет на текущие события. Например, из-за флешбека у руин окажется ранее спрятанный автокар, помогающий скрыться от погони. Аналитик не может вводить факты, которые полностью нивелируют вызов. Мастер назначает аналитику Бросок мистики (−6), при провале которой аналитик не сможет учесть всего и хоть добивается своего, но получает Невзгоды.",
  "Корректировка": "Псионик получает возможность мгновенно корректировать происходящее непосредственно рядом с собой. Корректировка: реакцией на краткосрочные действия видимой и находящейся в пределах 12 метров цели псионик тратит 2 пси и совершает Бросок мистики (−6), в случае успеха заставляя цель перебросить только что сделанную проверку. Обрывчатый анализ: аналитик тратит прогноз и 10 минут на концентрацию, после совершает Бросок мистики (−6). При успехе опишите ситуацию мастеру и спросите, что стоит сделать вашему аналитику. Мастер рассказывает короткую последовательность действий, не раскрывая ни их предпосылки, ни последствия.",
  "Социальная инженерия": "Псионик может проектировать сложные математические модели, позволяющие предсказывать поведение обществ и скоплений людей, а также влиять на них. Если псионик провёл день в определённом обществе, изучая его, или если псионик обладает отчётами о быте такого общества, то он может влиять на его поведение. Размер общества, на которое может оказать влияние псионик за одно использование способности, равен [100 × смекалка] человек. Затратив 6 пси и концентрируясь ещё 1к6 часов, псионик совершает Бросок мистики (−6), в случае успеха совершая необходимый аналитический расчёт. Если обладающий успешным расчётом псионик проведёт в данном обществе сутки, пообщается с его лидером на безобидные темы, или иным способом проведёт контакт с обществом, то на [категория успеха] недель такой псионик может наложить на целевое общество один из эффектов: в обществе назревают волнения и раскол; общество объединяется перед лицом выбранной псиоником угрозы; в обществе возникает беспочвенный или имеющий основания слух; в обществе набирают силы выбранные псиоником настроения; из-за несогласованности решений общество частично утрачивает организованность. Другой вероятностный аналитик может заметить, что на общество было оказано влияние, если преуспеет в Броске смекалки против смекалки применившего социальную инженерию псионика. При провале он может повторить проверку, лишь заполучив новые важные факты о попавшем под влияние обществе.",
  "Общение с духом": "Персонаж концентрируется 5 минут, тратит 1 пси и совершает Бросок мистики (−3). При провале способность расходуется до конца дня. За каждую категорию успеха от духов Асу шаман узнаёт одно из: есть ли в пределах 60 м от него пустоты, сильные искажения, скопления теней и области с высоким пси-полем (шаман может лишь ощутить их присутствие, а не понять точное расположение); есть ли в пределах 60 м вокруг живые существа, помимо тех, которых шаман видит (шаман может лишь ощутить их присутствие, а не понять точное расположение); примерное расположение известного живого существа, реликвии, объекта мира духов в пределах 60 м.",
  "Песнь жизни": "Раз в сцену персонаж тратит действие, 2 пси и совершает Бросок мистики (−6), обращаясь к Асу, чтобы те даровали поток жизни видимой цели в пределах 3 м. В случае успеха шаман может выбрать что-то одно: стабилизировать цель; снять с цели один протяжённый во времени и действующий сейчас эффект мистической способности; снять с цели одну пси-мутацию, если та ещё в состоянии метаморфозы.",
  "Саматха": "В начале игровой встречи возьмите кость к6 (это кость духов) и поставьте значением 1 вверх. Каждый раз, когда ваш шаман проваливает проверку мистики, повысьте значение на кости 1. Если число на кости достигает 6, то снизьте его опять до 1, но духи застилают разум шамана, и тот считается в состоянии саматхи. В саматхи персонаж садится на землю и со скоростью 1 см в минуту к ближайшей поверхности из тела начинают расти упругие, похожие на корни отростки псевдоплоти. Разум шамана блуждает в мире Нарра-Ка следующие к6 часов или пока шаман не умрёт. Совершите Бросок духа (−3): при провале шаман теряет 2 пси, поскольку саматха приносит кошмар (мастер может попросить описать его). При успехе духи научили шамана чему-то новому — тот восстанавливает [категорию успеха] пси и ОЗ. Раз в сцену шаман может сам повысить кость духов на 1, и перебросить проверку мистики.",
  "Духи жизни": "Раз в день, затратив 1 пси, шаман действием может совершить Бросок мистики (−3), в случае успеха заставляя окружающих Асу наполнить тело одной видимой им цели и даровать той исцеление. Цель восстанавливает [категорию успеха] ОЗ. После цель становится невосприимчива к эффекту способности до конца дня.",
  "Жизнь бьёт повсюду": "Совершив успешно проверку «духов жизни», персонаж может добавить к её эффекту ещё один: восстановить цели ещё 1 ОЗ; избавить цель от истощения; приблизить выздоровление любой травмы на 10 дней; снять с цели стресс.",
  "Отпугнуть жизнь": "Раз в день шаман может потратить 2 пси и собрать встревоженных Асу в своём теле на [дух] минут. Кость духа шамана растёт на 1, но все живые, видящие шамана существа должны совершить Бросок воли против мистики шамана, или будут испуганы. Испуг исчезнет, если шаман погибнет или существо не будет видеть шамана и будет считать себя вне его местоположения.",
  "Песнь мира": "Реакцией затратив 1 пси, шаман может совершить Бросок мистики (−3), в случае успеха успокаивая сонм Асу внутри и снижая значение Кости Духов на 1.",
  "Свет бытия": "Раз в день, затратив 2 пси и реакцию, шаман глубоко вдыхает и вбирает в себя окружающих Асу. Люди без пси-способностей слышат лишь шумный вдох, который характеризуется лёгким порывом ветра; тогда как псионик с мистикой 6+ может видеть, что шаман поглощает Асу не только ртом и носом, а буквально впитывает их всем телом. Шаман может растворить поглощённых Асу в себе, исцеляя свои раны, или же может исцелить другую цель в пределах 24 метров, резко выдохнув в её сторону поток крошечных светящихся духов. Шаман совершает Бросок мистики (−6), в случае успеха исцеляя [значение на к20] ОЗ цели, стабилизируя и снимая с неё все истощения и травмы. Свет бытия может даже воскресить существо, если оно погибло менее 5 минут назад. Если шаман не справляется с хлынувшими в его тело Асу и проваливает проверку с Невзгодами, он теряет 1 ОЗ.",
  "Аз есмь жизнь": "Затратив 2 пси, реакцией шаман совершает Бросок мистики (−3), желая испещрить своё тело духами Асу. В случае успеха шаман до конца сцены может использовать Значение своей мистики в проверках вместо Значения своей выносливости, получает Упрощение на все попытки себя стабилизировать и Упрощённо проходит спасброски от смерти, а также до конца сцены получает [кость духа + категория успеха] временных ОЗ.",
  "Встань и иди": "Раз в день, затратив 4 пси, персонаж реакцией совершает Бросок мистики (−6), в случае успеха восстанавливая весь запас здоровья себе или другой видимой биологической цели в пределах 60 м от себя. Эффект снимает все травмы, истощение, вредные состояния (кроме пси-мутаций) и воскрешает даже мёртвую цель, если та погибла менее суток назад.",
  "Прыжок в плоть": "2 раза в день, затратив действие и 1 пси, шаман может совершить Бросок мистики, желая направить своего Асу в тело цели в пределах 3 метров, в случае успеха нанося той [2 за категорию успеха] ран. Если мистика персонажа 6 и меньше, то сначала он должен 2 дня соблюдать пост, а затем впасть в двухчасовую медитацию, под конец которой заключит связь с духом.",
  "Атака роя": "Два раза в день, затратив 2 пси и действие, шаман может направить рой плотоядных Асу из своего улья в цель, о которой знает и которая находится в пределах 45 метров. Он совершает Бросок мистики против рефлексов цели. При успехе шаман изрыгает изо рта, носа и глаз волну Асу, которую каждый свидетель визуализирует в рамках своей психики (например, как рой плотоядных личинок, струю крови, разряд энергии, пламени, стаи саранчи и т.д.). Лишь псионики с мистикой 6+ способны увидеть в волне духов. Попавшие в тело жертвы духи начинают искать выход наружу сквозь плоть, разрушая её и мгновенно нанося цели [3 за категорию успеха] ран.",
  "Сожрать эмоцию": "Столкнувшись с чувственным переживанием или эмоциональным состоянием, раз в день затратив 1 пси, реакцией шаман может совершить Бросок мистики (−3), чтобы попытаться скормить переживание улью. Например, снять с себя состояние испуган, убрать срыв от провала проверки хладнокровия, временно нивелировать страстное желание или безудержное веселье. Также при помощи этой способности шаман может нивелировать потерю или получение пси, происходящие в результате переживания, но только если успешно применит способность в момент его получения. Сожравший эмоцию улей даёт +3 к ближайшей проверке отдыха персонажа.",
  "Защита роя": "Улей сам следит за психическими аберрациями пространства вокруг шамана и заранее отслеживает попытки повредить своего носителя. Два раза в день, если находящаяся в пределах 60 м от шамана и имеющая сознание цель собирается любым способом нанести ему физический вред, шаман может потратить 1 пси, свободным действием совершить Бросок мистики против воли цели. В случае успеха в разум цели впивается Асу, ошеломляет её, предотвращая исполнение намерения, и заставляет пропустить ход. Шаман не может применять эту способность более 1 раза на одну попытку цели.",
  "Солдаты роя": "Стоимость применения способности защита роя шамана повышается на 1 пси, однако теперь она ещё наносит цели [кость духа] ран.",
  "Мы есть одно": "Каждый раз, когда персонаж успешно применяет способность сожрать эмоцию, улей отдаётся теплом в теле и восстанавливает ему 1 ОЗ за сброшенный эффект и по 1 ОЗ за каждое 1 предотвращённое изменение пси. Например, если улей поглотил испуг персонажа, персонаж восстанавливает 1 ОЗ, а если в результате скормленных эмоций улей предотвратил потерю 2 пси, персонаж восстанавливает ещё 2 ОЗ.",
  "Атотызис": "Два раза в день, затратив действие и 2 пси, шаман может совершить Бросок мистики (−6), чтобы послать особых Асу в цель в пределах 60 м. В тело цели попадает [категория успеха] духов, каждый из которых разрушает свою псевдооболочку и гибнет во благо улья, нанося цели по 5 ран.",
  "Язык пустот": "Шаман может общаться на языке Нара. Высота характеристики «мистика» отображает то, насколько он хорош в этом. Чтобы «договориться» со слышащим его забывшим о выполнении простого, не приносящего очевидного физического вреда поступка, нужно затратить действие и успешно совершить Бросок мистики (−6). Для того чтобы временно успокоить слышащую шамана пустоту, понадобится затратить ход, 1 пси и успешно совершить Бросок мистики (−12). При провале переговоров с Невзгодами целевая сущность придёт в ярость.",
  "Приручение забывшего": "Шаман выслеживает гуманоидную тень — забывшего. Оказавшись в пределах 12 м, шаман тратит пару минут на общение с забывшим. Шаман «уговаривает» забывшего слушаться его, взамен разделяя с ним психическую энергию. Пока забывший служит шаману, каждую встречу он отнимает у шамана 1 пси. Шаман может приручить и контролировать одновременно лишь одного забывшего. В случае смерти шамана или тени процесс приручения придётся осуществлять заново. На этом уровне связи с шаманом тень по своей воле: не атакует своего шамана, а в ответ на его агрессивные действия спасается бегством; следует за телом шамана, если видит его, даже если шаман потерял дееспособность; убегает от сильных проявлений пси-поля, таких как несущие опасность искажения, пустоты, мистические способности; будет наивно пытаться осознать существ с сильным эмоциональным фоном в пределах 60 м от себя, атакуя их размашистыми ударами рук. Если шаман хочет заставить тень делать нечто другое, он должен реакцией озвучить слышащей его тени короткий приказ, который можно описать парой слов, и преуспеть в Броске мистики (−3). В случае провала шаман теряет 1 пси, а тень действует согласно своей логике до окончания 2 ближайших кругов. На мистике персонажа 6 и более шаман имеет над своим забывшим полную власть и больше не нуждается в проверках на контроль: свободным действием формирует желание в эмоциональный посыл, а забывший считывает его и повинуется, если находится в пределах 180 м и не скрыт полностью от шамана материалом с пси-сопротивлением выше 3. С этих пор забывший не будет атаковать близких шаману людей или ценные тому объекты, даже если шаман погиб или временно потерял дееспособность.",
  "Стенания пустоты": "Раз в день, затратив действие и 1 пси, шаман произносит фразу на языке сущностей Нара. Шаман испускает из своего рта волну пси-энергии в пределах 30 м вокруг. Не владеющие пси-способностями существа воспринимают её как глухой звуковой удар, сопровождающийся хриплой низкой речью. Звуковой удар резко сдвигает на 3 м от шамана все крошечные физические предметы, пускает дрожь в материальном пространстве, после чего вокруг возникает металлический запах крови, звучит шёпот, а у оказавшихся в радиусе действия способности гуманоидов и человекоподобных статуй выступают кровавые слёзы. Шаман совершает Бросок мистики против воли каждого значимого для истории существа, попавшего в радиус эффекта, нанося им по [2 за категорию успеха] ран. Не важные для истории существа без проверки получают по 4 раны. Попавшие под способность и неподконтрольные шаману тени и пустоты должны преуспеть в Броске воли (+3), или должны будут в страхе удаляться от шамана со своей максимальной скоростью в течение [категорию успеха] кругов.",
  "Многоликий Нара": "Шаман может превратить своего забывшего в демона изнанки — пустоту, или на языке дикарей «дэва-Нара». Забывший под контролем шамана может навсегда приобрести черту из описанных ниже, но не больше одной. Став подчинённым шаману Нара, сущность снижает пси своего повелителя на 2 каждую игровую встречу. Больше плоти: шаман должен найти второго забывшего в качестве жертвы. Если подчинённая шаману тень подойдёт и осторожно прикоснётся к жертве, то через мгновение под напевы шамана начнёт врастать ей в плоть. Через 15 минут жертва успокаивается, а забывший шамана навсегда получает торчащее из уплотнившегося туловища второе тело с головой, которое может действовать независимо. Теперь новое существо считается пустотой и совершает 2 независимые атаки в ход, а его внешний вид становится чудовищный. Телекинетические способности: шаман должен затратить 20 часов, покрывая тело забывшего сложными узорами под ритуальные напевы и помещая в его псевдоплоть шаманские атрибуты. В результате забывший становится пустотой и получает возможность применять тривиальную пси-способность телекинетика без траты пси и так, будто его мистика 9 (Бросок 19). Если пустота провалила проверку телекинетики, то она не может применять эту пси-способность до конца дня. Пространственное перемещение: шаман на протяжении 13 часов должен 13 раз поочерёдно окунуть своего забывшего в кровь и особые составы, после чего забывший обретает возможность применять пространственное перемещение (квантовая псинетика) на себя.",
  "Приказ": "Используя способность стенания пустоты, шаман подхлёстывает подчинённую ему и слышащую его тень или пустоту, мотивируя её ужасом либо восторгом (на свой выбор) и дарует ей +1 внеочередное действие.",
  "Разум, плоть, сущность": "Затратив 1 пси, шаман заставляет подчинённую тень или пустоту обернуть его своим телом, обманом вынудив других забывших или пустот с уровнем смекалки 0 и хуже принимать такой симбиоз за существо изнанки. Обманутые забывшие и не агрессивные пустоты не будут проявлять к такому существу враждебности. Псионики и шаманы могут распознать обман, пройдя Бросок восприятия (+6). Иные разумные существа могут распознать обман, только если их Значение искажений и реликвий 6+ и если успешно пройдут Бросок смекалки (−6). Симбиоз длится 15 минут или пока шаман не прекратит его. По его окончании шаман проходит спасбросок от пси-поля.",
  "Кара лжеца": "Персонаж выбирает одну цель в пределах 9 метров, способную слышать его. Персонаж тратит действие, 1 пси и совершает Бросок мистики против воли цели. В случае успеха всякий раз, когда цель пробует лгать, она чувствует чудовищную боль во рту, сравнимую с тем, будто она попыталась прожевать и проглотить ком из тысячи иголок, а из её рта потоком начинает идти кровь. Эффект длится 3 минуты за каждую категорию успеха.",
  "Как говорил Абсолютный": "Персонаж выбирает одну находящуюся под открытым небом и способную слышать его цель в пределах 75 м. Персонаж расходует 1 пси и тратит действие, чтобы выкрикнуть изречение Абсолютного. Он совершает Бросок мистики против воли цели. В случае успеха из туч вниз в цель бьёт испепеляющий столп света, ниспосланный из главного храма самим Абсолютным и молящимися вместе с ним праведниками. Цель получает [категории успеха] попаданий с МУ 13 энергия, раны 2.",
  "Молитва Абсолютному": "Раз в день культист может потратить 5 минут на концентрацию для помощи союзнику с аналогичной или отсутствующей религией. Культист восстанавливает 1 пси себе и [категория успеха] ОЗ цели, и должен преуспеть в Броске мистики (−3), или потратит молитву до конца встречи.",
  "Пламя Абсолютного": "Затратив действие и 2 пси, культист произносит вольную интерпретацию псалма гнева Абсолютного, и его символ раскаляется добела, испуская белый луч шириной 1 м и длиной до 30 м. Культист совершает Бросок мистики против рефлексов каждой цели, которая попадает под действие луча. В случае успеха цель нагревается и вспыхивает белым пламенем, получая [2 + категория успеха] попаданий с МУ 13 температура, раны 2. Против целей, которые являются псиониками или верующими в Асу, способность работает с модификатором +3.",
  "Порицание еретиков и грешников": "Затратив действие и 1 пси, персонаж выкрикивает порицающие слова. Культовый символ персонажа начинает излучать ошеломляющий и ослепляющий свет на цель, которая может видеть его и находится в пределах 30 м. Персонаж совершает Бросок мистики против воли цели, в случае успеха ослепляя ту на [1 + категория успеха] кругов. Если целью порицания является псионик или верующий в Асу, то культист получает +3 на данную проверку.",
  "Аутодафе": "Культист тратит действие, 3 пси и совершает Бросок мистики (−6), концентрируя внимание на точке в пределах 45 м от себя. В случае успеха фигуру культиста окружает ореол свечения, а квадратная область с гранью в 6 метров и центром в указанной точке покрывается ярко-белым пламенем необъяснимого происхождения. Каждое не обладающее верой в Абсолютного и оказавшееся в этой области существо теряет [6 ОЗ за категорию успеха]. Значимые для истории живые существа могут попробовать преуспеть в спасброске против пси-поля (−12), чтобы избежать повреждений.",
  "Вознесение": "Затратив 2 удачи, персонаж с мистикой 12+ может мутировать в новую форму жизни — Сверхчеловека. Сверхчеловек не имеет очков пси, кармы и не воскрешается реинкарнатором. Сверхчеловек — первоочередная цель атаки любых теней и пустот. Его разум не может утратить ясность из-за эмоций. У персонажа больше нет прежних недостатков, достоинств и мировоззрения. Его единственное достоинство — Сверхчеловек, и оно не может быть изменено. Его единственный недостаток — Сверхчеловек, и он не может быть изменён. У персонажа есть запас абсолюта, равный изначально 4. Персонаж получает 1 абсолют, когда действует для своих целей: без оглядки на сопутствующий ущерб непричастным; отвергая комфорт и безопасность; творя исторические события. Каждый раз, как персонаж отказывается следовать вышеперечисленному пути, он теряет 1 абсолют. Если абсолют персонажа должен опуститься ниже 0, то персонаж перестаёт быть Сверхчеловеком и никогда не может стать им вновь. Сверхчеловек получает 3 новые способности: Я есмь Сила — персонаж тратит 1 абсолют и может заменить итог любой своей проверки кости на значение 10; Я есмь Мощь — каждый раз, как персонаж должен применить мистическую способность, вместо траты пси он бросает к6 с Максимумом = абсолюту (если цена мистической способности 2 и выше пси, он получает −1 на эту проверку; при провале запас абсолюта падает на 1); Я есмь Сверхчеловек — когда персонаж первый раз сталкивается с объектом, местом или существом, он может затратить 1 абсолют и ввести в игру один новый факт из прошлого цели (факт не может полностью нивелировать вызов).",
  "Обрастание плотью": "Затратив действие и 1 пси, персонаж совершает Бросок мистики против выносливости видимой им цели в пределах 60 м. Если запас ОЗ цели полон, персонаж получает модификатор +3 на эту проверку. В случае успеха силой своих убеждений персонаж заставляет духов окутать тело цели и отдать тому свою жизненную силу, вызывая неконтролируемый и бурный рост псевдоклеток. Плоть цели начинает хаотично расти как вовне, так и внутрь, сдавливая все внутренние органы — цель теряет по 2 ОЗ за каждую категорию успеха. Если цель выжила, духи покидают её тело, псевдоплоть всасывается внутрь или отваливается, оставляя растянутую прежнюю или розовую новую кожу. Если способность приводит к смерти цели, то её тело взрывается огромными пластами плоти. Если культист проваливает проверку с Невзгодами, он восстанавливает цели 1 ОЗ.",
  "Дух хранитель": "Затратив действие и 2 пси, персонаж совершает Бросок мистики (−3), в случае успеха призывая духа Асу, который будет находиться рядом и хранить его покой [категория успеха] часов. Дух почувствует и пошлёт эмоцию-предупреждение, если в пределах 60 м от персонажа окажется кто-то, готовый навредить персонажу (ограбить, обмануть и т.д). Дух общается эмоцией, которую можно озвучить одним словом и которая не может раскрывать подробности ситуации. Культист может реакцией полностью поглотить духа, чтобы на [1 + категория успеха] кругов получить обострённое предчувствие опасности — не суммирующийся штраф −3 на все физические атаки по персонажу.",
  "Молитва Асу": "Раз в день, затратив 5 минут на разговор с духами о благополучии цели, культист наполняет себя и цель жизненной энергией и восстанавливает обоим по 1 пси. Культист должен преуспеть в Броске мистики (−3), или не сможет использовать молитву до конца встречи.",
  "Вселение в духа": "Концентрируясь в течение 10 минут и затратив 1 пси, персонаж совершает Бросок мистики (−3), в случае успеха вызывая лояльного духа Асу на [10 за категорию успеха] минут. Персонаж действием может перенести своё сознание в или из такого Асу. Дух способен двигаться сквозь пространство со скоростью 30 км/час, проходит сквозь любые объекты с пси-сопротивлением 3 и ниже, воспринимает объекты в пределах 60 метров. В проверках зрения духа используется смекалка персонажа вместо восприятия. Дух не подвержен эффектам плохой видимости и автоматически замечает все объекты с высоким эмоциональным фоном. Если псевдотело Асу погибает, персонаж грубо возвращает сознание в свою оболочку и теряет 2 пси.",
  "Беременность плотью": "Затратив действие и 2 пси, персонаж совершает Бросок мистики против воли слышащей и видящей его символ цели в пределах 60 метров. В случае успеха в желудке цели образовывается комок чужеродной пси-плоти. В конце каждого круга такая цель теряет [2 за категорию успеха] ОЗ и, если после остаётся в сознании, то совершает спасбросок выносливости (−3). Накопив суммарно 3 категории успеха в этих бросках выносливости, цель тошнит отвратительным комком плоти с шевелящимися отростками несформированных маленьких конечностей — эффект способности оканчивается. Если цель погибает, не успев прервать эффект, то из её тела выбирается крошечное, похожее на уродливого младенца существо-пустота, которое бежит к ближайшему мыслящему врагу.",
  "Призыв пустоты": "Культист тратит действие и 3 пси и совершает Бросок мистики (−6), добавляя как преимущество на эту проверку Вредность окружающего пси-поля (если то есть). В случае успеха по округе прокатывается шёпот, и из выбранного культистом места в пределах 30 м булькая начинает материализовываться пустота. Пустота слушается культиста ближайший час, после возвращая свободную волю. Пустота бездумно атакует всех враждебно настроенных к культисту существ. Культист может реакцией отдавать пустоте простые вербально-эмоциональные приказы. Если культист хочет заставить пустоту совершить нечто самоубийственное или очень сложное для её псевдоразума, то он должен затратить действие и преуспеть в Броске учения дикарей (Упрощённо, если культист говорит на языке пустот).",
  "Мучения праведны": "Персонаж выкрикивает любые слова о святости боли видимой и понимающей его цели, тратит действие, 1 пси и совершает Бросок мистики (−6) против воли цели. В случае успеха следующие [1 + категория успеха] кругов цель испытывает жуткие мучения, её поры кровоточат, глаза лезут из орбит, а мышцы сводит судорога. В начале каждого круга цель получает по 2 раны и должна совершать спасбросок воли (−3), при провале которого до конца круга получает истощение из-за боли.",
  "Боль безвинного": "Персонаж тратит час времени и 1 пси, распиная на священном символе одно живое существо и нанося на его тело тексты книги Этеменанки, а также произнося молитву боли и бытию. Существом может быть крыса, игуана, кот — кто угодно. Распятое существо должно подвергаться медленной и мучительной смерти, длительность которой [ловкость рук + 3] часов. Пока существо живо, а символ находится рядом с персонажем, персонаж может отменять наносимые ему раны — 2 раны за раз, если существо не обладает самосознанием, или 4 раны, если оно сознательное. Общее количество ран, которое может быть отменено, равно [мистика − 3]. Если запас блокируемых ран израсходован, существо в муках умирает от кровоизлияния в мозг. Персонаж одновременно не может иметь более одного распятого существа.",
  "Узы боли": "Затратив действие и 1 пси, культист выкрикивает священные слова о ненависти к себе, желая поразить одну цель, которая может видеть, слышать его и находится в пределах 30 м. Для этого он должен совершить Бросок мистики против воли цели. В случае успеха цель связана с культистом узами боли на [2 + категория успеха] круга. Связь пропадает, если культист утратит ясность ума (например, будет в шоке или оглушён). Каждый раз, пока связь существует и культист теряет ОЗ, цель теряет аналогичное количество ОЗ, даже если культист поглотил или отменил раны при помощи способности боль безвинного или ей подобных.",
  "Стигматы злобы": "Затратив действие и 2 пси, культист выкрикивает священные слова о том, как бытие ненавидит цель в пределах 60 м от него. Культист должен совершить Бросок мистики против воли цели. В случае успеха тело цели само подвергается разрушению и теряет по 1к6 ОЗ за каждую категорию успеха.",
  "Покаянное истязание": "Жрец Тофу тратит действие, 3 пси и совершает Бросок мистики (−6), внимая ко всей той боли, которой он предавался в последнее время. В случае успеха он на [1 + категория успеха] кругов разделяет эту боль между всеми видимыми им существами в пределах 36 метров перед собой, заставляя те извиваться в судорогах, визжать, рыдать кровавыми слезами и получать по 2к6 ран в конце каждого круга. Попавшее под действие покаяния значимое для истории существо в конце каждого круга может игнорировать этот эффект, если преуспеет в проверке к20 с Максимумом [воля + выносливость]. Жрец не совершает других ходов, пока не прекратит эту способность или пока не утратит ясность ума. Все поглощённые ОЗ в конце круга жрец забирает себе, за их счёт восстанавливая свой запас здоровья. Если при помощи этой способности жрец исцеляет свои ОЗ до максимума, то он избавляется от всех истощений и травм.",
  "Резонирующий голос": "За 1 пси монах действием может произнести фразу слышащей и понимающей его биологической цели. Монах совершает Бросок мистики против воли цели, в случае успеха цель впадает в отстранённый транс на минуту, или пока вокруг не случится что-то шумное или резкое. Если монах достиг успеха и на к20 выпало 6+, то очнувшаяся цель не помнит транс и не связывает его с монахом, а при успехе с Благом монах может дать цели простой и безопасный для неё приказ, который цель попробует выполнить за время транса. При провале цель невосприимчива к резонирующему голосу до конца встречи.",
  "Истовый исихазм": "Осмысливая во время ежедневных медитаций одновременно всемирный треугольник и ничтожность своего существования относительно выживания рода человеческого, монах обретает мистическую стойкость к бытовым потребностям. Затратив 1 пси, он совершает Бросок мистики (−3), за каждую категорию успеха на весь следующий день отказываясь от одного из вида потребностей без последствий: от еды, от воды, от сна или от отдыха. Отказавшись от отдыха, культист становится неутомим и получает автоматический успех во всех проверках, связанных с длительными физическими нагрузками.",
  "Моё тело — сосуд для воли предков": "Раз в день ради Великого Обновления рода человеческого монах может обратиться к хранящейся в генах памяти своих предков. Свободным действием он тратит 1 пси и совершает Бросок мистики (−6), в случае успеха перебрасывая свою проверку характеристик личности или тела (кроме выносливости).",
  "Молитва": "Раз в день, затратив 5 минут на осмысление пути гонимого воина и Великого Обновления, персонаж восстанавливает 1 пси и до конца дня получает возможность заставить противника перебросить одну проверку, направленную против себя не мистической атаки. Монах должен преуспеть в Броске мистики −3, или потратит молитву до конца встречи.",
  "Странник по изнанке": "Обладая целым культовым символом на момент смерти, монах может затратить 2 пси и через стандартный срок возродить себя в виденном ранее реинкарнаторе вместе с символом и 3 ключевыми для себя и находящимися с ним на момент смерти предметами.",
  "Смерть, друг мой, путь мой ещё не закончен": "Если монах упал в обморок или погиб, но его культовый символ цел, в начале нового круга монах может затратить 3 пси и совершить Бросок мистики (−6). В случае успеха с Невзгодами монах мгновенно восстанавливает 6 ОЗ, а в случае успеха без Невзгод полностью исцеляется, снимает все травмы, истощение и вредные состояния, тело монаха само становится в вертикальное положение. В случае провала монах больше не может использовать эту способность до конца дня. Если данная способность вернула персонажа к дееспособности в бою, то он проходит проверку инициативы.",
  "Даровать смерть": "Действием затратив 3 пси, персонаж совершает Бросок мистики против выносливости видимой им живой цели, в случае успеха с Невзгодами опуская все её очки здоровья до 0, а в случае успеха без Невзгод опуская её очки здоровья до состояния −100% и расщепляя в кровавую кашу. В случае успеха с Благом мастер может сказать, что существо погибло безвозвратно, его не воскресит реинкарнатор, но где-то родился новый ребёнок.",
  "Гибернация": "Затратив 5 минут и 1 пси, монах может замедлить процессы своего организма настолько, что кажется мёртвым и иссушённым. В этом состоянии он может спать десятки лет, не нуждаясь в еде, воде и воздухе и не проходя проверки отдыха и спасброски от смерти. Когда монах очнётся, то в течение часа ему нужно выпить и съесть 4 свои дневные нормы, в противном случае он погибнет.",
  "Электромеханическая пунарджанма": "Культист тратит действие и 1 пси, вознося хвалу Техно-Атману сломанного механизма рядом с собой, превознося его сущность, делясь с ней энергией и бережно прося поработать ещё немного. Культист совершает Бросок мистики, в случае успеха механизм временно «чинится» на [3 за категорию успеха] кругов и начинает работать вопреки всякой логике. Электромеханическая пунарджанма включает в себя именно починку и не может запустить механизмы с другими категориями проблем (например, с отсутствующим источником энергии).",
  "Общение с Техно-Атманом": "Культист тратит действие, 1 пси и совершает Бросок мистики (−3), пытаясь обратиться к сути находящегося в пределах 60 м механизма. Культист может узнать [категория успеха] следующих фактов о механизме: активен ли он ещё; каково его предназначение; зона его действия; понятный способ деактивировать его, не уничтожая; иную информацию, которую мастер сочтёт соразмерной.",
  "Молитва сотворённым инструментам": "Раз в день персонаж проводит 5 минут за молитвой, восстанавливая 1 пси и получая возможность один раз до конца дня поглотить до 3 ран из одного попадания, если оно нанесено устройством из 2 деталей и более (например, винтовкой, луком, ножом и т.д.). Культист должен преуспеть в Броске мистики (−3), или не сможет использовать молитву до конца встречи.",
  "Универсальный инструмент": "Персонаж тратит 1 пси, действие и совершает Бросок мистики (−6), в случае успеха на 1 час преобразовывая символ в любой инструмент от автогена до отвёртки. Этот инструмент можно применить по назначению не больше чем в [категория успеха] проверках.",
  "Анализатор окружающей среды": "Персонаж тратит 1 пси, действие и совершает Бросок мистики (−3). В случае успеха его культовый символ на 5 минут превращается в прибор, анализирующий Вредность окружающей среды в пределах 9 м. Анализатор даёт сведения по поводу [категория успеха] типов Вредности.",
  "Даруй мне оружие": "Персонаж реакцией тратит 1 пси и совершает Бросок мистики (−3), в случае успеха преобразовывая инструмент в небольшое энергетическое оружие, которое можно применить по назначению на ближайшие [категория успеха] атак. Такое оружие имеет характеристики Дл 15, Ат −3, МУ 15 энергия, Сл 0, раны 2.",
  "Паралич атмана": "Персонаж тратит 1 пси и действием пытается засунуть священный символ в электронный прибор. Если прибор движется, персонажу нужно сначала попасть, преуспев в Броске рефлексов против рефлексов прибора. Если символ достиг цели, то персонаж совершает Бросок мистики (+3) против защиты прибора от энергии. В случае успеха прибор утрачивает функциональность на [1 + категория успеха] кругов.",
  "Орбитальный удар": "Персонаж тратит действие, 3 пси и совершает Бросок мистики (−6). В случае успеха персонаж связывает свой дух с дремлющей на орбите древней машиной, и та испускает на указанную и открытую для небес видимую цель орбитальный удар. За каждую категорию успеха персонаж может выбрать для атаки ещё одну новую цель, при этом каждая дополнительная цель не должна находиться далее чем в 30 м от предыдущей. Каждая цель получает 6 попаданий с МУ 15 температура, раны 3. Значимые для истории существа могут избежать попаданий, если реакцией выберут меньшую характеристику среди лёгкой атлетики или рефлексов и преуспеют в её Броске (−9). Пси-сопротивление цели не может помочь от этой способности. Способность даруется вместе с усилением «даруй мне оружие»: создаваемый им лучестрел получает черту автомат.",
  "Грибной отвар": "Культист тратит 10 минут, рацион чистой воды, 1 пси и совершает спасбросок мистики (+3). В случае успеха он готовит [категория успеха] порций белёсого и безвредного отвара из грибов священной грибницы. Будучи выпитой в ближайшие 30 минут, эта порция на целый день насыщает и утоляет жажду одному персонажу, лечит 1 ОЗ и снимает 1 истощение. Если у персонажа отсутствуют вредные состояния и истощения, священный отвар даст ему бодрость. В день персонаж может получить эффект только от одной порции грибного отвара. Священной грибнице требуется восстановить свой урожай, поэтому культист может вновь попробовать приготовить отвар лишь на второй день после этого.",
  "Ядовитая слизь": "Культист тратит 30 минут, 1 пси и совершает спасбросок мистики (−3). В случае успеха из выделений слизней культист готовит [категория успеха] порций бесцветного и безвкусного яда. Порция имеет размер примерно с кончик большого пальца, и её хватает, чтобы отравить один приём пищи. Такой яд сохраняет свойства до 3 суток, а будучи принятым внутрь, вынуждает цель пройти спасбросок от химии (−9). При провале цель повторяет спасбросок не 1/день, а 1/круг, и после каждого повторения есть шанс 1 из 6, что заражение закончится. При успехе спасброска цель лишь в шоке на ход и её просто тошнит. Слизням священной грибницы требуется восстановление, поэтому вновь приготовить яд культист может попробовать лишь на третьи сутки после предыдущей попытки.",
  "Гиперчувствительность рецепторов": "Реакцией затратив 1 пси, персонаж съедает одного из слизней грибницы и совершает Бросок мистики (−3). В случае успеха токсины в теле слизня активируют часть нервной системы персонажа, на [20 за категорию успеха] минут повышая на 6 восприятие всех органов чувств. Одновременно персонаж может находиться только под одним таким эффектом, а если на персонажа действуют сразу два эффекта, учитывается наиболее протяжённый из них.",
  "Молитва окружающей среде": "Раз в день, затратив 5 минут на молитву, персонаж переживает мистический опыт, восстанавливая 1 пси и получая возможность до конца встречи один раз добавить +3 к проверке путника на Равнине, связанной с природой проверке или к проверке с участием своей выносливости. Культист должен преуспеть в Броске мистики (−3), или не сможет использовать молитву до конца встречи.",
  "Растворить яд и болезнь": "Свободным действием персонаж тратит 1 пси и совершает Бросок мистики (−6), в случае успеха до конца дня получая Упрощение на проверку отдыха и все свои проверки выносливости, которые призваны защитить организм персонажа от яда и болезней. Одновременно персонаж может находиться только под одним эффектом от данной способности.",
  "Токсичность мёртвых тел": "Потратив реакцию в свой ход, персонаж расходует 1 пси и заставляет часть паразитов внутри послушно умереть. Их тела распадаются в крови, наполняя ту ядовитыми, повышающими реакцию персонажа веществами. Персонаж получает ещё 1 действие и совершает Бросок мистики (−10), в случае провала в конце круга получая истощение, а если он уже истощён — болезнь. Способность можно применять не чаще, чем раз в круг."
};


const ARCHETYPES = { avantyurist: ARCHETYPE_ADVENTURER, boec: ARCHETYPE_FIGHTER, diplomat: ARCHETYPE_DIPLOMAT, intellektual: ARCHETYPE_INTELLECTUAL, kultist: ARCHETYPE_CULTIST, psionik: ARCHETYPE_PSIONIC, shaman: ARCHETYPE_SHAMAN };
function currentArchetype(c){ return ARCHETYPES[c.archetypeKey] || ARCHETYPE_ADVENTURER; }
// Flavor blurbs for the "Выберите архетип" hover hints — стр. 50, the book's own short description of
