const ARCHETYPE_DESCRIPTIONS = {
  avantyurist: 'Это плуты и хитрецы, полагающиеся на скрытность и уловки. Это проворные воры, скрытные убийцы, опытные проводники и хитрые мошенники.',
  boec: 'Это грозные воители, всегда готовые к бою. Суровые солдаты, идущие на штурм в силовых экзоскелетах, опытные охотники за головами, железной хваткой держащие след, и бешеные берсерки, сокрушающие врагов из ощетинившихся стволами тяжёлых орудий.',
  diplomat: 'Там, где оружие бессильно, решают связи и умение вести дела. Дипломаты — это умелые переговорщики, харизматичные соблазнители, ловкие лжецы и вдохновляющие лидеры.',
  intellektual: 'Знание — это сила, с которой приходится считаться. Гениальные врачи, устанавливающие мощные аугментации, робототехники, собирающие собственных гумоидов, и хитроумные хакеры, взламывающие древние терминальные системы в поисках утерянных тайн.',
  kultist: 'Это люди, подавляющие реальность силой своих убеждений. Паладины, движимые непоколебимыми религиозными принципами, сокрушающие в бою врагов церкви; и капелланы, наставляющие нуждающихся союзников и уничтожающие еретиков верой, воплощённой в грозных мистических умениях.',
  psionik: 'Это безумцы и схизматики, способные слышать мысли людей и голоса песков; сенсорики, считывающие эмоции окружающих и отпечатки этих эмоций на материальных объектах; могучие психокинетики, сминающие противников силой своих способностей, и аналитики реальности — предсказатели, рассчитывающие вариативность пространства-времени.',
  shaman: 'Это люди, чтящие духов, новый мир и ищущие в нём гармоничную нишу для человека. Это ведуны, соединяющиеся с духами в новое целое и с их помощью повелевающие окружающим пространством. Знахари, способные одним прикосновением втянуть в себя жизнь и вдохнуть её в умирающего. И повелители химер из псевдоплоти.'
};
// Same, for origins (стр. 67-72) — condensed from the book's longer per-origin paragraphs to fit the
// 500-char hint budget, keeping the actual book wording rather than paraphrasing into new sentences.
const ORIGIN_DESCRIPTIONS = {
  zhitel_goroda: 'Выросшие в городе горожане слабо подготовлены к испытаниям Равнины и имеют штраф на иммунитет. Выросшие в шумном социуме, они лучше врут, торгуются, доказывают свою правоту и быстрее принимают решения — бонус к убеждению, артистизму и смекалке. Живут за стенами и спинами стражи, поэтому реже прячутся от набегов — зато лучше образованы и разбираются в истории нового мира и теологии.',
  zhitel_sela: 'Жители села вырастают в голоде посреди химического ада Равнины: получают случайное уродство, штраф выносливости, могут снизить размер. Живя без излишеств и занимаясь ручным трудом, получают неприхотливость и небольшое преимущество на ловкость рук. Из-за набегов каннибалов и мародёров полагаются на осторожность — бонус к восприятию, лёгкой атлетике и молитве. Хуже распознают ложь.',
  dikar: 'Дикари живут в химических лесах, постоянно голодая: штраф к силе и выносливости, размер небольшой. Иммунитет закалён постоянным пребыванием на Равнине — бонус. Участвуют в жестоких сражениях за ресурсы и владеют архаичным оружием. Хуже распознают ложь и ораторствуют. Ручная работа в лесах даёт бонус ловкости рук и скрытности. Хранят культурные традиции — поклонение духам Асу, бонус к духу и молитва.',
  strannik: 'Странники — одинокие скитальцы по пескам Равнины: поиски древнего хлама, новых мест, попытки поймать удачу. Часто голодают — бонус к проверке отдыха, штраф выносливости. Полагаются на опыт выживания, внимательность и незаметность — бонус к восприятию и хорошая скрытность. Хуже распознают ложь. Привыкшие полагаться только на себя — бонус к смекалке или воле. Не получают бонус ловкости рук.',
  kochevnik: 'Регулярный голод и жизнь среди ядовитых песков дают номадам штраф к выносливости. С детства перебираются по племенным автокарам и мотобайкам — бонус к акробатике, рефлексам и вождению, а постоянный мелкий ремонт даёт бонус ловкости рук. Много путешествуя, табор лучше понимает мир и сталкивается с искажениями предтеч. Редко бегает или прячется — штраф к лёгкой атлетике и скрытности.',
  odichaly: 'Одичалые — чумные каннибалы, некромастеры, отшельники и безумцы Равнины: получают сильное уродство. Поедая человеческую плоть, их тела крупнее и сильнее. Прошедшие через горнило права сильного — бонус к силе воли и лёгкой атлетике, но не к скрытности. Примитивные племенные правила развивают веру в духов и фобию к древним технологиям.'
};
// Карьеры (стр. 52-66) — each one's own book flavor paragraph (trimmed to ~500 chars at a sentence
// boundary where the original ran notably longer), used verbatim rather than a mechanical summary.
const CAREER_DESCRIPTIONS = {
  "agrariy": "Сыпучая и безжизненная земля никак не хочет прорастать скудными урожаями. Мелкие сёла строят чахлые, хлопочущие клеёнкой на ветру теплицы, способные рождать лишь отравленные посевы. Такие посевы крестьяне перетирают в муку и готовят ядовитый хлеб, провоцирующий болезни и химические интоксикации. Крупные города-государства и феодальные правители строят целые тепличные комплексы, в которых пытаются поддерживать все необходимые условия для взращивания пшеницы. Однако ламп дневного света вечно не хватает, плодородной почвы ещё меньше, а большие объёмы чистой воды обходятся в безумные суммы денег.",
  "akter": "Разве благодарное это занятие — давать выступления перед нищими под звук собственного бурчащего живота? Вашу жизнь нельзя назвать лёгкой, скорее это судьба. Каждый новый выход на пластиковый помост — это выслушивание скабрезных шуток от местных подонков и вторящего им громкого хохота пьяных наемников. Что не лучше скучающих взглядов аристократов и богачей во время представлений на празднествах. Всё это может вынести лишь человек, обожающий своё ремесло. Или тот, кто сам собирается обчистить карманы всех этих недалёких идиотов.",
  "aristokrat": "Вы являетесь потомком аристократа. Ваша юность прошла за муштрой современной геральдики, истории, теологии и даже крупиц древних знаний, сокрытых в ваших семейных застенках. К сожалению, в эти сложные времена многие знатные роды разоряются на фоне гибнущего мира, ударяются в ультранасилие, бездумно тратят свои сбережения на бесконечные оргии и балы. А некоторые из семей просто не способны привить отпрыскам надлежащее послушание, и те покидают отчий дом в поисках приключений.",
  "veshun": "Вы один из самых уважаемых людей в племени — от вас зависит предсказание движения химических бурь, поиск новых источников влаги, успешность охотничьих вылазок и благословение на сбор ресурсов для племени. Вы — говорящий с песками, вы проводник между обычными людьми и духами самой жизни, между повседневным миром и его мистическим круговоротом энергии. Пусть духи ещё и не являлись вам лично, однако ваша вера в них не слепа, а крепко закреплена теми благами и чудесами, которые жизнь даёт в ответ на ваши молитвы.",
  "voin": "Вы не знаете офицерской муштры, не умеете ходить строем и не разбираетесь в чинах. Вы — воин племени, герой, ваше прошлое связано со сражениями, а не с болтовнёй за кружкой очищенной воды. Вы проявили себя как крепкий боец и хорошо обращаетесь с оружием. Война — не ваше место службы — это ваше призвание!",
  "voriwka": "Вы всю жизнь несётесь сквозь городские прилавки, спасая свою шкуру от только что ограбленного «сытого». Вы знаете все крупные местные банды и хорошо представляете, в каких закоулках лучше скрываться от городской стражи.",
  "vrach": "кочевник. Вы привыкли штопать раны, лечить химические отравления, выслушивать жалобы и пытаться облегчить боль тех, кто получил смертельную дозу радиоактивного облучения. Вы один из самых уважаемых людей в социуме. Врач на Равнине — это сокровище, поэтому вам не часто приходилось защищать свою жизнь.",
  "glashatay": "Быстро бегать и громко орать про очередные новости — вот ваша работа. Когда казни, пьяная оргия, эпидемия, радиоактивная буря, а когда сбор на войну с соседним городом — всё это вы узнаёте первым и срочно сообщаете окружающим. Кроме того, вы умеете читать и писать!",
  "golovorez": "Не каждый готов сутками вкалывать на воздухоочистительных заводах. Нищета и голод порождают тех, кто берёт в руки оружие и идёт за чужим куском канцерогенного хлеба. Вам хорошо известно, каково это. Свою жизнь вы провели на городских улицах, грабя в подворотнях, участвуя в кровавых разборках местных банд или убивая на заказ.",
  "digger": "Говорят, когда-то Свалка была полна разных древних сокровищ. Импульсные батареи, работающие древние терминалы и гумоиды, ящики оружия и медикаментов. Когда-то? Сейчас это лишь жалкие остатки былого богатства. И вот уже много лет вы тщетно роетесь в них, с ног до головы покрытые отравляющими веществами, тяжело дыша сквозь маску и выискивая тот самый клад, который таки сделает вас счастливым.",
  "eretik": "Церковные культы давно проявили свою монополию на людей с пси-способностями, выискав их среди последних родившихся, кто сколько успел. Что не досталось культам — отправилось в цепкие лапы частных аристократов или осело в холодных руках корпораций. Однако на ядовитых просторах Равнины остались ещё одинокие безумцы, которые смогли пробудить свои мистические силы вне городов, за пеленой песчаного покрова, в посёлках аборигенов, в диких архаичных племенах одичалых или среди шумных сборищ мотоциклетных банд. Горе им, если попадут они в лапы инквизиции.",
  "zhurnalist": "Малая замшелая газетёнка, написанная на перетёртой и сваренной древней бумаге, выглядит жёлтой и одинокой. Она немощно трепещет в руках на ядовитом ветру. Однако на этой газетёнке сбоку внизу есть ваше имя! Имя, написанное под очередной вашей разоблачительной статьёй! Это ли не счастье? Жаль, читать умеют лишь избранные крохи населения.",
  "zodchiy": "Где и как в городе поставить смотровые вышки? Как организовать подъёмные ворота и как их встроить в структуру стен? Как из ломаных древних небоскрёбов собрать трёхэтажное здание администрации так, чтобы оно не обвалилось внутрь? Как построить городской общественный туалет? Вы нужны городу, и он платит вам звонкой монетой за ваши труды.",
  "izvozchik": "Крупные города живут своей быстрой жизнью. Чиновники и клерки в стёртых древних костюмах спешат по пыльным улицам на работу, сменщики фильтров бредут к ядовитой яме колодца, а за ними носильщики-зазанты на крюках тянут сменные фильтрационные диски. Где-то шумят ещё пьяные боевики корпоративных армий, обсуждая подавление бунта рабочих, бастующих по поводу повышения налога на чистый воздух. И вся шумная городская жизнь, суета — это всё ваша стихия. Подобрать опаздывающего юриста и подбросить к зданию суда, а затем словить пьяных боевиков и подвезти их к борделю на окраине...",
  "klerk": "Вы родом из крупного города, и каждый ваш день начинается с отряхивания костюма и похода на унылую работу. Работу, которая считается куда более престижной, чем просиживание штанов у мануфактурного станка. Ваша жизнь так однообразна, что вы даже не уверены в этой «престижности». Сидячий образ жизни и постоянные переработки плохо сказались на вашем состоянии здоровья, сделали вас более скрытным, научили переносить монотонный стресс и лучше разбираться в окружающей лжи.",
  "krestyanin": "Вы провели жизнь в глухом селе, вспахивая чахлые грядки в клеёнчатых теплицах. Серые пески, яростные химические бури, набеги каннибалов и голодные будни — вот спутники вашей безрадостной жизни. Мучаясь от ужасающего кашля и боли в груди, регулярно умирая под чёрными небесами Равнины, вы неистово молились последнему известному вам свету надежды — Абсолютному: «спасся он и остался, да спасёмся мы вслед за ним!» Вот понятный и простой путь, а все эти старые технологии — это порождение зла, разрушившее мир.",
  "marodyor": "странник, кочевник. Вы представитель одной из самых многочисленных профессий на территории Свалки — мародёр. Крадучись по пескам, вы отлавливаете путников, диггеров со скарбом и бредущих со своим жалким товаром крестьян. Угрозами ли, или применяя насилие, вы добиваетесь того, что вам нужно — еды на ещё один день. Новый мир диктует свои условия, ведь никто не знает, какова будет его старость.",
  "marshal": "Вы реализовали себя в поиске и поимке тех, кто посягает на чужое имущество. Крупные города кишат мелким ворьем и маститыми заправилами организованных преступных группировок. Многие из них у вас на слуху. А часть из них вы даже приволокли в короткие руки современного закона и обрекли на рабство в шахте или даже множественную смерть. Впрочем, вам же за это и платят.",
  "melnik": "На окраинах городов и у крупных сёл стоят огромные ветряки, вращающие свои лопасти, чтобы производить электричество, перемешивать регенераторные жидкости или перемалывать ядовитую муку. Если город крупный и может позволить себе электростанцию — молотилки могут и не зависеть от природной энергии. Однако пылевые ветра вездесущи, бесплатны и беспощадны, что и приводит к широкому распространению использования их ресурса. Вы работаете на такой мельнице. Перетаскивание бочек и уход за ветряком — не самая большая плата за сытое тело.",
  "motovod": "Ветер Равнины вот уже много лет стучит песком в стёкла вашего противогаза, когда вы несётесь на племенном мотобайке, обвешанном флагами с защитными руническими символами и угрожающими религиозными посланиями вашим врагам. Вы настоящий мотовод, способный договориться с древним духом автокара и заставить его есть заряженные частицы, порождая скорость.",
  "naemnik": "странник, кочевник. Вы — не благородный воин или борец за права и идеалы, если таковые ещё и остались. Кто больше платит — тот и получает вас с крепко зажатым в руке оружием. Вы прошли жестокий путь — от охранника каравана до феодального солдата. Горнило безжалостного мира и бесконечные сражения закалили вас и сделали опасным противником.",
  "nosilshik": "Ваша крупная нога ступает в сыпучий песок и проваливается почти по колено. За вашей спиной огромный рюкзак, груженый чужим товаром на продажу. Вы оглядываетесь и видите позади воющую серую пыль. Пыль сливается в однородное месиво и скрывает всё происходящее уже метрах в ста. Вы смотрите в её завихрения, и вам кажется, будто вы смотрите не просто на движения крошечных частичек, а на всю вашу жизнь: всё так же ваша нога проваливается в песок, всё так же вы тащите чужие вещи под шумные окрики охранников каравана, в перерывах играя в карты или поедая варево одноразовых супов.",
  "otstupnik": "В детстве в твой дом пришла процессия из нескольких мрачных фигур в рясах и группы вооружённых солдат. Вместо их лиц и лиц своих родителей ты помнишь только размытые кляксы. Фигуры в рясах о чём-то общались с твоими родителями, солдаты скучали. А потом тебя увели. До сих пор ты пытаешься понять, страдали ли родители, или с радостью обменяли проклятого ребёнка на годовой продовольственный пай. В любом случае твои дальнейшие будни были связаны с послушанием и монастырскими традициям. Будни ребёнка, скованного рамками религиозных догматов, не выглядят как лучшее детство.",
  "otshelnik": "Вы построили свою жизнь вокруг одиночества и аскезы. Тихая, неприметная жизнь посреди полных опасностей песков прошла в постижении тайн бытия. И пусть она не помогла вам лучше понять других людей, зато позволила пролить свет на новые знания и закоулки вашей собственной души.",
  "ohotnik": "Остатки фауны пока могут прокормить ещё более жалкие остатки былой человеческой цивилизации. Вы умеете пробираться по исчезающему на песке следу ментатаракана, ставить силки на игуан крыс, находить воду в уходящих под землю этажах разрушенных небоскрёбов. Однако год уходит за годом, и вы в очередной раз пробираетесь по пескам с тяжёлой тушей крысиного мутанта на спине, обжигая едким потом глаза под душной маской противогаза. Быть может, это не всё, для чего вы были рождены?",
  "pastuh": "Забота о животных и беспокойство об их здоровье — вот чем вы были заняты большую часть своей жизни. Вы разбираетесь в том, как найти с ними общий язык, как приручить или отпугнуть. Не самая статусная профессия, зато у вас был доступ к свежему мясу.",
  "pisar": "Мало кто умеет читать и писать не то что на довоенном диалекте, но и на общем. Для заполнения договоров, личных документов, прав собственности и прочего простому люду (а бывает, даже и зажиточным феодалам) нужен писарь. Это престижная работа со множеством привилегий. Ваша мама была права — церковное образование таки вам пригодилось. Пусть вам и приходится теперь постоянно общаться со множеством других людей.",
  "plut": "кочевник. Честный труд не для вас, счастья с ним не нажить. Однако всё не так плохо, ведь если Бог и бросил этот мир, то он хотя бы не забрал с собой простофиль. А пока есть простофили, ваша жизнь не будет такой уж голодной. Пусть вы непримечательный плут, но вы хотите верить, что рано или поздно урвёте тот самый заветный большой куш.",
  "povar": "Те крохи, что нынче именуются пищей, не располагают ко множеству сложных кулинарных изысков. Однако и на просторах Равнины находятся люди, отдающие себя во власть поварского искусства. Где-то в глухом селе кто-то печет химически вредный хлеб, экспериментируя с мукой. А кто-то, сидя в тёмных городских подворотнях под трубами воздуховода, жарит чумных крыс, фаршированных плесневой пастой. Где-то грязный, обвешанный животными костями одичалый с любовью срезает мясо для стейка со спины орущего пленника.",
  "prostitutka": "Молодость мимолётна, а пустой желудок заставляет попрощаться с ней ещё быстрее. Продавать своё тело — это ещё не худшее решение в текущих реалиях. Особенно если ты вышел мордашкой. Мир катится в тартарары, а значит, каждому может понадобиться тепло и утешение. Так что первое, чему ты научилась на своей работе, это слушать. Второе — слушать правильных людей.",
  "rabochiy": "Вы знаете, работая ли на мануфактурном производстве патронов, или на воздухоочистительном заводе, или вкалывая на осколке древнего гиганта, производящего энергию на одну миллионную от своих прежних мощностей — каждый рабочий вынужден гнуть спину на ярмо корпораций и феодалов. Вы все трудитесь до седьмого пота, а получаете гроши. Но лучше уж так, чем с покрытыми опухолями дыхательными путями и чёрными химическими слезами каждый день ползать в развалинах и думать, сможешь ли ты сегодня купить кусок хлеба или нет. Лучше уж стабильность, пусть и жалкая.",
  "remeslennik": "Среди болезней и ультранасилия ещё остались те, кто способен что-то создать своими собственными руками. Будь то башмачник, который покрывает горячим соком лу подошву древних армейских ботинок, защищая её от кислотности почвы. Или дикарь, склонившийся над костюмом из дерева чу и плетущий сложную вязь из его молодых веточек. Или человек, раскалённым гвоздём наносящий сложную роспись на древний пластиковый судок. Всё это ремесленники, зарабатывающие упорным трудом.",
  "rostovshik": "Пусть простой люд и не любит вас, а многие даже считают скрягой, однако что вам их косые взгляды, если в вашей суме всегда водятся деньги.",
  "skitalec": "Разные культуры и новые территории всегда манили вас, а песок Равнины под ногами всегда был роднее тёмных утрамбованных камней брусчатки мегаполиса. Вы жили в лесу, вы отлёживались с ранениями в чахлых крестьянских домиках, собранных из глины и бетонных обломков многоэтажек. Вы даже видывали развалины предтеч, сплошь кишащие странными человеческими фигурами, которые вам не удалось хорошо рассмотреть, но которые вызвали ощущение инородности и тошноты…",
  "sluga": "Многие считают, что вам несказанно повезло. Вместо того, чтобы склониться с больной спиной над станком или, будучи перемотанным дешёвыми повязками, менять пылерез над городской стеной, вам выпало счастье служить аристократам. Вы могли бы с этим поспорить, ведь некоторые забавы увядающих от старости и сходящих с ума от безысходности богатых людей могут ужаснуть и самых заядлых палачей. Вы бы могли, но еженедельная сухая ванна и кусок вяленого мяса ментатаракана на вашем хлебе мешают вам спорить слишком громко.",
  "soldat": "Если корпорации предпочитают наёмников, то правители и аристократия часто делают ставку на призыв населения в свои армии. Солдатами могут быть дети крестьян, ремесленников или зажиточных купцов — каждый может отравиться на войну ради целей правителя. Эта судьба постигла и вас — вы прошли не один региональный конфликт и знакомы с суровыми буднями походов. Война может и не быть вашим призванием, но это то, что вы умеете делать.",
  "stercorarius": "Мало кто позавидует вашей профессии, которую простолюдины называют «говночерпий». Лишь в развитых городах есть канализация, а фекалии нужно убирать и доставлять на фермы. Годы спусков в узкие лазы, полные ядовитых паров и испражнений, исказили ваше тело. Теперь вы скрываетесь от чужих глаз в тёмных переулках. Пусть так, ведь вы не брезгливы, а деньги не пахнут.",
  "teoretik": "Сидя в тёмной пыльной комнате, склонившись над разбитым стеклом ещё работающего терминала данных, вы жадно пытались поглотить все оставшиеся крупицы знаний предтеч. Вы убеждены: новый мир — это лишь ничтожные осколки старого, а все мистические тайны и секреты существования лежат именно в древних оцифрованных текстах старых электронных носителей. Пусть такой образ жизни и не сделал из вас могучего воина, однако истинная сила для вас лежит в совсем другой плоскости.",
  "teurg_cifrovyh_sistem": "Цифровые специалисты — большая редкость в современном мире, особенно на территории Свалки. Корпоративные службы выискивают способных ребят и натаскивают их настраивать и обслуживать свои терминальные сети данных, обеспечивая хранение и защиту информации. Однако лишь редкие одиночки осваивают древнюю науку, просиживая дни над обветшалыми сенсорными устройствами и пытаясь самостоятельно разобраться в древней иероглифике операционных систем времён Катаклизма.",
  "tehnik": "кочевник. Ваши одежды в следах копоти и пятнах машинного масла, вы с самых юных лет роетесь в ломаном железе древних и новых технологий, пытаясь придать ему некое подобие функциональности. Технический кузнец ценится в любом обществе, ведь куда лучше иметь исправный автомат, чем ещё одного врага.",
  "torgovec": "Условные дороги посреди пепельных песков Свалки нетнет, да и пропустят по себе четыре-пять десятков груженных тюками людей. Перекрикиваются охранники с трубчатыми автоматами, шумно пыхтят потные и сидящие на зазе носильщики. Это караван. А караван — это новые фильтры, вода, еда, новые медикаменты и оружие, это сама жизнь пустынной Равнины. И раз эта жизнь передвигается между поселениями, поддерживая их тлеющее бытие, значит, кто-то должен эти товары продавать.",
  "travnik": "Многие годы вы занимались травничеством в химически изувеченных лесах, общались с духами, помогали раненым, плели поделки из веток Чу и заговаривали предметы. Ваше лицо покрыто ритуальными татуировками, религиозными плагами и украшениями. Фигура занимающегося знахарством травника в племени является приближенной к природе, что позволяло вам, насколько возможно, держаться подальше от сражений.",
  "traktirshik": "Небольшие питейные заведения в мелких и крупных городах традиционно пользуются спросом у простых работяг, шахтёров, наёмников и прочего сброда. Выпивка, минимальный набор простой еды и изредка комнаты для ночлега — всё это то, что нужно людям после тяжёлого рабочего дня или перехода по Равнине. Расслабиться, рассказать пару мутных слухов, приукрасить новости или заключить не совсем честную сделку в тёмном углу. Однако теперь это в прошлом. Кто знает, что заставило вас покинуть свой засаленный передник и привычный вечерний гомон посетителей.",
  "uchitel": "Мало кто имеет хоть какое-то образование, не говоря уже про то, чтобы передать его другим. Ваши клиенты — дети богатых купцов, аристократические семьи и корпоративные менеджеры, работающие с современными терминалами. Платят хорошо, когда есть заказы. Когда есть…",
  "fermer": "Выращивание ментатараканов — занятие пусть и не благородное, зато обеспечивающее настоящим мясом. Тяжёлый физический труд, общение с животными и хорошее питание закалили ваше тело. А простой быт, борьба за выживание и религиозный социальный строй привили если не истовую веру, то послушание.",
  "cerkovnik": "одичалый. Где бы ни прошло ваше прошлое, связано оно было со служением вашему культу. В ужасе приближающегося затухания всей человеческой расы вы стали на путь надежды, каким бы мрачным этот путь ни казался. Первобытные верования одичалых каннибалов, пропитанные запахом человеческого пота, испражнений и крови. Или яростная, слепая вера в Абсолютного. Грохот колёс под песни Технологическому Превосходству, безжалостная аскеза и уединения Чёрных Монахов или неистовый экотерроризм во имя Матери Природы — всё это поиск пути к спасению.",
  "chinovnik": "Сборщики налогов, мелкие управители, земельные чиновники и секретариат городской администрации — всё это люди на службе города. Ваши будни проходят за просиживанием часов над архивными записями о жителях поселения, решением их имущественных споров и разбирательствах об уплаченных налогах.",
  "shahter": "Раз в двадцать лет можно встретить сумасшедшего, что расскажет, будто мир когда-то вспух во множестве мест и породил вспышки, которые стёрли города и извратили то, что не исчезло в ярости термических реакций. Выпучив безумные глаза, такой сумасшедший будет утверждать, будто плоть лилась и забирала в себя людей, превращая тех в химер и прочие порождения зла, которыми сейчас пугают глупых прихожан священники Абсолютного. Скорее всего, вы никогда и не встречали такого сумасшедшего.",
  "mentalnye_resursy": "Монотонная и безжалостная работа в виде корпоративного детектора лжецов, воров и нелояльных специалистов убивает ваши нервы. Постоянные головные боли и шёпот, слышимый в одинокой тишине ночных кошмаров… Он приходит всегда с одной и той же стороны — со стороны Равнины. Вы можете позволить себе лучшие обезболивающие, но даже они не способны полностью снять эту свинцовую тяжесть в голове, похожую на застывший там комок слипшейся крови. Это всё сумасшедший график вашей работы — эти бесконечные опросы и выезды на переговоры."
};

// Подтипы (стр. 88+) have no comparable flavor paragraph in the book — they go straight into their
// mechanical bonus tables — so their hover hint is built here instead, straight from the subtype's own
// (book-sourced) first-level bonuses and named ability, rather than invented prose. Cached per key
// since the underlying data never changes at runtime.
const _hintCache = {};
function summarizeModsForHint(mods){
  const fixed = summarizeFixedMods(mods);
  const firstAbility = mods.find(m=>m.t==='ability' && m.name!=='Профессия');
  const parts = [];
  if(fixed.length) parts.push(fixed.slice(0,4).join(', '));
  if(firstAbility) parts.push(`«${firstAbility.name}»: ${firstAbility.text}`);
  let text = parts.join('. ');
  if(!text) text = 'Бонусы не фиксированы — распределяются или выбираются при создании.';
  return text.length>500 ? text.slice(0,497)+'…' : text;
}
function hintForSubtype(key){
  if(_hintCache['sub:'+key]) return _hintCache['sub:'+key];
  let found=null;
  Object.values(ARCHETYPES).forEach(arch=>{ if(arch.subtypes[key]) found=arch.subtypes[key]; });
  const firstLevel = found && Object.keys(found.levels).map(Number).sort((a,b)=>a-b)[0];
  const text = found ? summarizeModsForHint(found.levels[firstLevel]||[]) : '';
  return _hintCache['sub:'+key] = text;
}


// Лежит в первом блоке скриптов, а не в 05-game-table.js: лог бросков (10-session-xp.js) рисует значок травмы
// ещё при загрузке страницы, когда блок игрового стола не запущен.
/* Природа существа: травмы бывают только у гуманоидов и животных; у пустот травм нет; у роботов вместо травм —
   поломки 🔧 (тот же порог «к12 выше Травма-к12»). Явно — поле «Природа» (шаблон бестиария и жетон: nature),
   иначе по шаблону: способность «Робот» — робот; «пустот» в группе, фракции или названии — пустота (кроме
   одержимого: у него тело носителя). */
const CREATURE_NATURES = {living:'гуманоид / животное', void:'пустота', robot:'робот'};
function creatureNature(c){
  if(!c) return 'living';
  if(CREATURE_NATURES[c.nature]) return c.nature;
  if((c.abil || []).some(a=>/^\s*робот\s*$/i.test(String(a && a[0] || ''))) || /(?:^|[^а-яё])(?:робот|андроид|гумоид)/i.test(c.name || '')) return 'robot'; // гумоид — робот: поломки вместо травм
  if(/одержим/i.test(c.name || '')) return 'living';
  return /пустот/i.test([c.group, c.faction, c.name].join(' ')) ? 'void' : 'living';
}
function tokenNature(t){ return t && CREATURE_NATURES[t.nature] ? t.nature : t && t.creature ? creatureNature(t.creature) : 'living'; }
// значок травмы (🦴) или поломки робота (🔧); red — от оружия с чертой «травма»
function traumaIconHtml(robot, red, n){
  return `<span${red ? ' class="bone-red"' : ''} title="${robot ? 'Поломка' : 'Травма'}${red ? ' (черта оружия «травма»)' : ''}">${robot ? '🔧' : '🦴'}</span>${n > 1 ? n : ''}`;
}
